describe('Admin Pending Approval - Waiting Room UI', () => {
  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'pendinguser',
          email: 'pending@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'unassigned',
        status: 'pending',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getPendingSession');
  });

  it('pending user visits /pending-approval → renders approval pending card and action buttons', () => {
    cy.visit('/pending-approval');

    // Heading & explanation
    cy.contains('h1', 'Approval Pending').should('be.visible');
    cy.contains(
      'p',
      'Your account has been registered and is currently waiting for administrator review.',
    ).should('be.visible');

    // Action buttons
    cy.contains('button', 'Check Status').should('be.visible').and('not.be.disabled');
    cy.contains('button', 'Log Out').should('be.visible').and('not.be.disabled');
  });
});

describe('Admin Pending Approval - Status Checks', () => {
  beforeEach(() => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'pendinguser',
          email: 'pending@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'unassigned',
        status: 'pending',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getPendingSession');
  });

  it("click 'Check Status' while still pending → displays pending status message", () => {
    cy.visit('/pending-approval');

    cy.contains('button', 'Check Status').click();

    cy.contains('Your account is still pending approval. Please check back later.').should(
      'be.visible',
    );
  });

  it("click 'Check Status' after admin approval → redirects to / dashboard", () => {
    let isApproved = false;

    cy.intercept('GET', '**/auth/session*', (req) => {
      if (isApproved) {
        req.reply({
          statusCode: 200,
          body: {
            role: 'member',
            status: 'active',
            tenant: {
              id: 't-1',
              name: "Delisha's Kitchen",
              slug: 'delisha-kitchen',
            },
            isImpersonating: false,
          },
        });
      } else {
        req.reply({
          statusCode: 200,
          body: {
            role: 'unassigned',
            status: 'pending',
            tenant: null,
            isImpersonating: false,
          },
        });
      }
    }).as('getSession');

    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: { totalRecipes: 0, recentRecipes: [] },
    }).as('getHome');

    cy.visit('/pending-approval');
    cy.contains('h1', 'Approval Pending')
      .should('be.visible')
      .then(() => {
        // Simulate approval before clicking check status
        isApproved = true;
      });

    cy.contains('button', 'Check Status').click();

    cy.url().should('match', /\/$/);
    cy.contains('h2', 'Recent Creations').should('be.visible');
  });

  it("click 'Check Status' when blocked → displays account blocked message", () => {
    let isBlocked = false;

    cy.intercept('GET', '**/auth/session*', (req) => {
      if (isBlocked) {
        req.reply({
          statusCode: 200,
          body: {
            role: 'unassigned',
            status: 'blocked',
            tenant: null,
            isImpersonating: false,
          },
        });
      } else {
        req.reply({
          statusCode: 200,
          body: {
            role: 'unassigned',
            status: 'pending',
            tenant: null,
            isImpersonating: false,
          },
        });
      }
    }).as('getSession');

    cy.visit('/pending-approval');
    cy.contains('h1', 'Approval Pending')
      .should('be.visible')
      .then(() => {
        // Simulate block before clicking check status
        isBlocked = true;
      });

    cy.contains('button', 'Check Status').click();

    cy.contains('Your account has been blocked by the administrator.').should('be.visible');
  });
});

