describe('Admin Pending Approval - Route Guards', () => {
  it('pending user navigates to / → redirected to /pending-approval', () => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'pendinguser',
          email: 'pending@example.com',
        },
      },
    }).as('getCurrentUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'unassigned',
        status: 'pending',
        tenant: null,
        isImpersonating: false,
      },
    }).as('getPendingSession');

    cy.visit('/');

    cy.url().should('include', '/pending-approval');
    cy.contains('h1', 'Approval Pending').should('be.visible');
  });

  it('active user navigates to /pending-approval → redirected to /', () => {
    cy.intercept('GET', '**/auth/me*', {
      statusCode: 200,
      body: {
        user: {
          username: 'activeuser',
          email: 'active@example.com',
        },
      },
    }).as('getActiveUser');

    cy.intercept('GET', '**/auth/session*', {
      statusCode: 200,
      body: {
        role: 'member',
        status: 'active',
        tenant: {
          id: 't-1',
          name: "Delisha's Kitchen",
          slug: 'delisha-kitchen',
        },
        isImpersonating: false,
      },
    }).as('getActiveSession');

    cy.intercept('GET', '**/api/home*', {
      statusCode: 200,
      body: { totalRecipes: 0, recentRecipes: [] },
    }).as('getHome');

    cy.visit('/pending-approval');

    cy.url().should('not.include', '/pending-approval');
    cy.contains('h2', 'Recent Creations').should('be.visible');
  });
});
